/** Readable workings for the current run. This module never changes the solver. */
import {AIR,N2,gasConstant,atmosphere,gasState,fanSystem,nozzleSupply,regulatorSettings,sizeLiftThroat,gasInventoryAtRegulator} from './hardware.js?v=4.4';
const G=9.80665;
const n=(value,d=1)=>Number.isFinite(value)?value.toLocaleString('en-US',{minimumFractionDigits:d,maximumFractionDigits:d}):'not available';
const esc=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const line=html=>`<div class="calculation-line">${html}</div>`;
const step=(heading,html)=>`<li><strong>${heading}</strong>${html}</li>`;
const note=text=>`<p class="math-caveat">${text}</p>`;
const symbols=text=>`<p class="math-symbols">${text}</p>`;
function card(number,id,title,formula,result,steps,definitions,caveat,visibleCaveat=''){
 return `<article class="calculation-card" id="calc-${id}"><span class="calculation-number">${number}</span><h3>${title}</h3>${line(formula)}<p class="math-result">${result}</p>${visibleCaveat?note(visibleCaveat):''}<details class="calculation-details" id="math-${id}-details"><summary>Show substitution and assumptions</summary><ol class="calculation-steps">${steps.join('')}</ol>${symbols(definitions)}${note(caveat)}</details></article>`;
}

/** All displayed numbers come from the selected inputs or the returned solver result. */
export function renderMathExplanation(result){
 const r=result,p=r.p,hw=r.hardware,m=p.mass,amb=atmosphere(p),initial=gasState(p,p.gas),supply=nozzleSupply(p,initial);
 const fan=r.ramp?fanSystem({...p,fanPower:Math.min(p.fanPower,p.batteryPower)}):hw.fan;
 const weight=m*G,volume=p.tankVolume/1000,gasR=gasConstant(p),fluidWord=p.gasModel==='air'?'air':'nitrogen',idealPressure=p.gas*gasR*amb.T/volume;
 const leak=fan.leakArea,low=amb.p-fan.delta,ratio=low/amb.p,critical=(2/(AIR.gamma+1))**(AIR.gamma/(AIR.gamma-1));
 const regulator=regulatorSettings(p),inventory=gasInventoryAtRegulator(p),sizing=sizeLiftThroat(p);
 const reference=p.realGas&&p.gasModel!=='pr',optimistic=p.feedModel==='optimistic';
 const eosPressureCaveat=p.realGas?(reference?'This run uses shipped CoolProp reference '+fluidWord+' tables, with bilinear interpolation in entropy and log density. States outside validated table cells stop thrust.':'Peng–Robinson comparison: the default fill is 440.6 bar versus 492.5 bar from the reference EOS. This optional approximation has a state-dependent bias.')+' <a href="#eos-reference">Reference model and scope ↗</a>':'';
 const eosTemperatureCaveat=p.realGas?(reference?'Tank and regulator reference properties are coupled into this flight; the result is recomputed, not shifted by a fixed temperature correction. Saturation or invalid table cells stop thrust.':'PR comparison: at 117 kg on the default matched isentrope, PR gives about −84.5°C versus −92.5°C from the reference EOS. A PR thermal pass remains provisional.')+' <a href="#eos-reference">Reference model and scope ↗</a>':'';
 const cards=[];
 cards.push(card('01','mass','How heavy is the complete car?',
  'm<sub>wet</sub> = m<sub>vehicle</sub> + m<sub>battery</sub> + m<sub>tanks</sub> + m<sub>fans</sub> + m<sub>lines</sub> + m<sub>gas</sub>',
  `The run starts at <strong>${n(m,0)} kg</strong>; weight = <strong>${n(weight/1000,2)} kN</strong>.`,[
  step('Add the component budget.',line(`${n(hw.structure,0)} + ${n(hw.batteryMass,0)} + ${n(hw.tankMass,0)} + ${n(hw.fanMass,0)} + ${n(hw.ancillaries,0)} + ${n(p.gas,0)} = <strong>${n(hw.minimumWetMass,0)} kg</strong>`)),
  step('Calculate the battery mass.',line(`m<sub>battery</sub> = E / e = ${n(p.batteryEnergy,0)} × 1,000 Wh / ${n(p.packDensity,0)} Wh/kg = ${n(hw.batteryMass,0)} kg`)),
  step('Apply the requested mass.',`<p>Requested: ${n(hw.requestedMass,0)} kg. ${p.enforceHardware?'The integration uses the greater of requested mass and the component budget.':'Hardware mass enforcement is off; the requested mass is used even if it is below the component budget.'}</p>`),
  step('Convert mass to weight.',line(`W = mg = ${n(m,0)} kg × 9.80665 m/s² = ${n(weight,0)} N`))],
  'm is mass in kg; W is weight in newtons (N). 1 kN = 1,000 N. Stored gas is included in wet mass.',
  'Component masses, pack density and the requested vehicle mass are assumptions. The default gas capacity is a reported manufacturer claim; the selected value is not measured inventory. Actual mass falls as gas leaves the car.'));

 cards.push(card('02','fan','What airflow and fan power hold it to the ramp?',
  'S = Δp A; &nbsp; Δp<sub>target</sub> = suction ratio × mg / A',
  `Steady achieved suction: <strong>${n(fan.actualSuction/1000,1)} kN</strong>, using <strong>${n(fan.inletQ,2)} m³/s</strong> at the fan inlet and <strong>${n(fan.power/1000,1)} kW</strong>.`,[
  step('Find the target pressure difference.',line(`Δp<sub>target</sub> = ${n(p.suction,2)} × ${n(m,0)} × 9.80665 / ${n(p.sealedArea,2)} = ${n(fan.target/1000,2)} kPa`)),
  step('Add the leakage openings.',line(`A<sub>leak</sub> = Lg + A<sub>extra</sub> = ${n(p.sealPerimeter,2)} m × ${n(p.fanGap/1000,4)} m + 0.0004 m² = ${n(leak,4)} m²`)),
  step('Calculate compressible leakage.',line('ṁ = C<sub>d</sub>A<sub>leak</sub> p<sub>a</sub> / √(RT) × √{2γ/(γ−1) [β<sup>2/γ</sup> − β<sup>(γ+1)/γ</sup>]}')+`<p>β = max(p<sub>low</sub>/p<sub>a</sub>, 0.528); the lower bound represents choking for γ=1.4. At the achieved pressure difference ${n(fan.delta/1000,2)} kPa: p<sub>low</sub>/p<sub>a</sub> = ${n(ratio,3)}, β = ${n(Math.max(ratio,critical),3)}, and ṁ = ${n(fan.mdot,2)} kg/s.</p>`),
  step('Convert flow and compression work.',line(`Q<sub>inlet</sub> = ṁRT/p<sub>low</sub> = ${n(fan.inletQ,2)} m³/s`)+line('P<sub>fan</sub> = ṁ c<sub>p</sub>T [(p<sub>a</sub>/p<sub>low</sub>)<sup>(γ−1)/γ</sup> − 1] / (η<sub>fan</sub>η<sub>motor</sub>)')+`<p>Use ṁ=${n(fan.mdot,2)} kg/s, T=${n(amb.T,2)} K, c<sub>p</sub>=1,004.675 J/(kg·K), η<sub>fan</sub>=${n(p.fanEfficiency,2)}, η<sub>motor</sub>=0.94. Result: ${n(fan.power/1000,1)} kW. Ambient-volume flow is ${n(fan.ambientQ,2)} m³/s; fan-inlet volume is larger at lower pressure.</p>`),
  step('Compare target with available hardware.',`<p>${fan.canReachTarget?'The target is within':'The target exceeds'} the selected fan limits. ${r.ramp?'During the climb, suction builds with time and fan power shares the battery budget.':'This is a steady surface-adhesion screen.'}${fan.targetOutsideModel?' The requested pressure difference exceeds the model’s 90%-of-ambient limit.':''}</p>`)],
  'S is suction force (N); A is sealed floor area (m²); L is seal perimeter; g here is gap size, not gravitational acceleration. Cᵈ=0.65 is assumed. Air uses R=287.05 J/(kg·K), γ=1.4.',
  'For a small pressure difference, Q≈CᵈAₗₑₐₖ√(2Δp/ρ) and P≈ΔpQ/η are useful approximations. The numbers above use compressible flow and compression work. Fan curves, seal dynamics and duct losses remain assumptions; suction provides no lift after release.'));

 const ramp=r.ramp;
 if(ramp){
  const end=ramp.final,omega=Math.abs(end.omega),wheelPower=end.drivingForce*ramp.surfaceRadius*omega;
  cards.push(card('03','ramp','Can it drive all the way up?',
   'P<sub>battery</sub> = P<sub>fan</sub> + F<sub>wheel</sub> Rω / η<sub>drive</sub>',
   ramp.released?`Release after <strong>${n(ramp.time,2)} s</strong> at <strong>${n(ramp.exitSpeed,2)} m/s</strong>; peak demand <strong>${n(ramp.peakPowerW/1000,1)} kW</strong>.`:`<strong>No ramp release.</strong> ${esc(ramp.reason)}`,[
   step('Define the circular path.',line(`R = ${n(ramp.surfaceRadius,2)} m; r₀ = R − 0.60 m = ${n(ramp.geometricRadius,2)} m; r = r₀ − z<sub>CG</sub> = ${n(ramp.cgRadius,2)} m`)+`<p>Driving target: ${n(ramp.p.speed,2)} m/s. The climb starts from rest; its achieved speed is calculated.</p>`),
   step('Solve forces and pitch rotation together.',line('J = m(r² + x<sub>CG</sub>²) + I<sub>y</sub>')+line('Jα = R(F<sub>wheel</sub> − F<sub>rolling</sub>) − mg(r sinφ + x<sub>CG</sub> cosφ) − F<sub>drag</sub>r₀')+line('N = S + mg cosφ + m(rω² + x<sub>CG</sub>α)')+`<p>The calculated minimum contact normal force is ${n(ramp.minimumNormal/1000,2)} kN. Wheel force is limited by μ × driven-load fraction × N, the ${n(p.driveForce,1)} kN wheel-force setting, and available motor power. Here μ=${n(p.tyreGrip,2)} and the driven-load fraction is ${n(p.drivenLoad,2)}.</p>`),
   step('Show the electrical balance at the last ramp sample.',line(`P<sub>wheel</sub> = ${n(end.drivingForce/1000,2)} kN × ${n(ramp.surfaceRadius,2)} m × ${n(omega,3)} rad/s = ${n(wheelPower/1000,2)} kW`)+line(`P<sub>battery</sub> = ${n(end.fanElectricalPower/1000,2)} + ${n(wheelPower/1000,2)} / 0.90 = ${n(end.batteryPower/1000,2)} kW`)+`<p>This is an endpoint value. The maximum over the whole climb is ${n(ramp.peakPowerW/1000,1)} kW against a ${n(p.batteryPower,0)} kW battery budget. The motor has its own ${n(p.drivePower,0)} kW electrical limit.</p>`),
   step('Integrate energy rather than multiplying by peak power.',line(`E<sub>ramp</sub> = ∫ P<sub>battery</sub> dt = ${n(ramp.batteryEnergyJ/3.6e6,3)} kWh`))],
   'φ is the ramp angle; ω=dφ/dt is angular speed; α=dω/dt. R is surface radius, r₀ the body-center radius, r the radial CG distance, N normal force, J generalized rotational inertia.',
   'This is a constrained planar ramp with an assumed 90% drive efficiency. Bank, entry transition, wheel spin, individual axle loads and suspension are unresolved. A stalled attempt does not continue into a fictional flight.'));
 } else {
  cards.push(card('03','ramp','What does the separate ramp screen assume?',
   'N = S + mg cosφ + mv²/r; &nbsp; grip = μ f<sub>drive</sub>N',
   `Airborne-only mode: <strong>no driven climb is simulated</strong>. Steady-speed power screen: <strong>${n(hw.peakRampElectricalPower/1000,1)} kW</strong>.`,[
   step('Assume constant speed along the selected arc.',`<p>v=${n(p.speed,2)} m/s, surface radius R=${Number.isFinite(hw.rampRadius)?n(hw.rampRadius,2)+' m':'a flat, zero-angle release'}, minimum normal force ${n(hw.minimumNormal/1000,2)} kN. The screen samples the arc from 0° to ${n(p.pitch,1)}°.</p>`),
   step('Compare grip with gravity-climb demand.',line('F<sub>available</sub> = μ f<sub>drive</sub>N; &nbsp; F<sub>demand</sub> = mg |sinφ|')+`<p>Minimum grip/demand ratio: ${Number.isFinite(hw.gripMargin)?n(hw.gripMargin,2):'not applicable when gravity-climb demand is zero'}.</p>`),
   step('Estimate steady electrical demand.',line(`P<sub>fan</sub> + P<sub>gravity-climb</sub>/0.90 = ${n(fan.power/1000,1)} + ${n(hw.rampGravityPower/1000,1)} / 0.90 = ${n(hw.peakRampElectricalPower/1000,1)} kW`))],
   'N is force normal to the ramp. μ is the selected friction coefficient; fdrive is the assumed share of normal load carried by driven wheels.',
   'This screen omits acceleration, motor torque limits and fan startup. Enable “Start by driving up the ramp” to integrate those effects and calculate the release state.'));
 }

 cards.push(card('04','storage','How much tank pressure and space are needed?',
  'pV = Z m<sub>gas</sub> R<sub>gas</sub>T',
  `<strong>${n(p.gas,0)} kg</strong> in <strong>${n(p.tankVolume,0)} L</strong> gives <strong>${n(initial.invalidState?NaN:initial.pressure/1e5,0)} bar absolute</strong> in the selected gas model.`,[
  step('Convert the volume and find the ideal-gas comparison.',line(`V = ${n(p.tankVolume,0)} L / 1,000 = ${n(volume,3)} m³`)+line(`p<sub>ideal</sub> = ${n(p.gas,0)} × ${n(gasR,3)} × ${n(amb.T,2)} / ${n(volume,3)} = ${n(idealPressure/1e5,1)} bar`)+`<p>This comparison uses ${p.realGas?fluidWord:'air'} in both cases. 1 bar = 100,000 Pa; pressure is absolute.</p>`),
  step('Apply the selected equation of state.',reference?line('s₀ = inverse T(s, ρ₀); p = bilinear[p(s₀, log ρ)]')+`<p>The table contains the reference ${fluidWord} EOS sampled by CoolProp. Initial entropy is found from temperature and density; pressure interpolation gives Z=${n(initial.invalidState?NaN:initial.Z,3)} and p=${n(initial.invalidState?NaN:initial.pressure/1e5,1)} bar. No extrapolation is allowed.</p>`:p.realGas?line('p = R<sub>u</sub>T/(v̄−b) − a(T)/(v̄²+2bv̄−b²)')+`<p>The optional Peng–Robinson equation gives Z=${n(initial.invalidState?NaN:initial.Z,3)} at this density and temperature. Therefore p=Z × p<sub>ideal</sub> = ${n(initial.invalidState?NaN:initial.pressure/1e5,1)} bar.</p>`:`<p>Ideal-air mode assumes Z=1, so the selected pressure equals the ideal value.</p>`),
  step('Include the empty pressure vessels.',line(`m<sub>tanks</sub> = p<sub>rating</sub>V / index = (${n(p.tankRating,0)} × 100,000 × ${n(volume,3)}) / (${n(p.tankIndex,0)} × 1,000) = ${n(hw.tankMass,0)} kg`)+`<p>This uses the assumed vessel rating, ${n(p.tankRating,0)} bar, rather than the current gas pressure.</p>`),
  step('Check external dimensions, not internal litres alone.',`<p>The custom 2:1 split gives vessels of ${n(hw.large.outerLength,2)} m × Ø${n(hw.large.outerDiameter,2)} m and ${n(hw.small.outerLength,2)} m × Ø${n(hw.small.outerDiameter,2)} m. Extra clearance is ${n(p.installationClearance,0)} mm on each side/end. ${hw.packageFits?'The idealized components fit the selected bays.':'At least one selected component exceeds its assumed bay.'}</p>`)],
  'Z is compressibility factor; Rgas is the specific gas constant; T is in kelvin. The PV/mass index is an assumed vessel performance metric, not a certified wall design.',
  'The default 600 L and 250 kg reflect reported capacity. Gas type, initial temperature, custom tank dimensions, ratings and internal bays remain model assumptions. Reference gas properties and bounding boxes do not establish real component qualification or whole-car fit.',eosPressureCaveat));

 cards.push(card('05','regulator','Can the feed deliver pressure and flow together?',
  optimistic?'p<sub>n</sub> = p<sub>ceiling</sub>; &nbsp; ṁ<sub>feed,max</sub> = ṁ(p<sub>tank</sub> → p<sub>ambient</sub>)':'p<sub>n</sub> ≤ p<sub>ceiling</sub>; &nbsp; ṁ<sub>feed</sub>(p<sub>n</sub>) ≥ ṁ<sub>nozzles</sub>(p<sub>n</sub>)',
  `<strong>${optimistic?'Optimistic independent bound':'Consistent pressure/flow solve'}</strong>. Setpoint: <strong>${n(regulator.regulatorBar,0)} bar</strong>; initial pressure ceiling: <strong>${n(initial.feedPressure/1e5,1)} bar</strong>. ${r.hasGasFlow?`Lowest flowing nozzle-inlet pressure: <strong>${n(Number.isFinite(r.minimumManifoldPressure)?r.minimumManifoldPressure/1e5:null,1)} bar</strong>.`:'No flowing nozzle-inlet state was reached.'}`,[
  step('Apply the setpoint and delivery loss as a pressure ceiling.',line('p<sub>ceiling</sub> = max[p<sub>ambient</sub>, min(p<sub>set</sub>, p<sub>tank</sub>)(1 − loss/100)]')+line(`p<sub>ceiling,initial</sub> = max[${n(amb.p/1e5,3)}, min(${n(regulator.regulatorBar,1)}, ${n(initial.invalidState?NaN:initial.pressure/1e5,1)}) × (1 − ${n(regulator.deliveryLossPercent,1)}/100)] = ${n(initial.feedPressure/1e5,1)} bar`)+`<p>The ${n(regulator.regulatorBar,0)} bar setpoint and ${n(regulator.deliveryLossPercent,1)}% loss are adjustable assumptions. The default solve can lower pressure below this ceiling; loss no longer creates an independent feed-flow allowance.</p>`),
  optimistic?step('Keep the optimistic comparison explicit.',line('ṁ<sub>feed,max</sub> = 0.8 A<sub>feed</sub> G(p<sub>tank</sub>, p<sub>ambient</sub>, T<sub>tank</sub>)/√max(0.3, Z)')+`<p>This mode caps total flow with tank-to-ambient discharge while keeping nozzle pressure at the ceiling. The two can be mutually unattainable. A contact pass under this bound does not establish a pass under the consistent feed solve.</p>`):step('Solve one shared nozzle-inlet pressure.',line('ṁ<sub>feed</sub>(p<sub>n</sub>) = 0.8 A<sub>feed</sub> G(p<sub>tank</sub>, p<sub>n</sub>, T<sub>tank</sub>)/√max(0.3, Z)')+line('ṁ<sub>nozzles</sub>(p<sub>n</sub>) = Σ min[F<sub>lagged,i</sub>, F<sub>cap,i</sub>(p<sub>n</sub>)] / v<sub>e</sub>')+`<p>Try the pressure ceiling first. If feed inflow cannot meet nozzle demand there, bisect between ambient and the ceiling until the two flows match. Clip each lagged jet force to its capacity at that same pressure. If feed capacity is sufficient at the ceiling, the regulator meters the requested flow and no pressure reduction is needed.</p>`),
  step('Inspect the selected feed and the solved run.',line(`A<sub>feed</sub> = πd²/4 = π(${n(p.feedDiameter/1000,3)})²/4 = ${n(Math.PI*(p.feedDiameter/1000)**2/4,6)} m²`)+`<p>${r.hasGasFlow?`${optimistic?'This comparison does not apply a pressure reduction.':'The feed '+(r.feedBindingOccurred?'binds for '+n(r.feedBindingTime,3)+' s':'does not require pressure reduction')+' in this run.'} Maximum demand above same-pressure feed capacity is ${n(r.maximumFeedDeficit,5)} kg/s${optimistic?'; a positive value exposes the optimistic bound’s pressure/flow inconsistency':'; the consistent solve keeps this residual at numerical zero or below'}.`:'No gas discharge was integrated.'}</p>`),
  step('Locate the tank-pressure boundary.',inventory.available?line(`m<sub>above setpoint</sub> = ${n(p.gas,1)} − ${n(inventory.gasAtSetpoint,1)} = ${n(inventory.gasAboveSetpoint,1)} kg`)+`<p>${esc(inventory.reason)}${!inventory.initialAboveSetpoint?' The tank begins at or below the setpoint.':''}</p>`:`<p>${esc(inventory.reason)}</p>`),
  step('Size the four lift throats at the initial pressure ceiling.',line('A<sub>each</sub> = (F<sub>rating</sub>/4)/(G<sub>effective</sub>v<sub>e</sub>); d = 2√(A/π)')+(sizing.diameterMM!==null?`<p>At ${n(initial.feedPressure/1e5,1)} bar and ${n(initial.feedTemperature,1)} K, the minimum calculated diameter is ${n(sizing.diameterMM,2)} mm per lift nozzle. Current selection: ${n(p.throat,1)} mm. Nozzle discharge coefficient: 0.90.</p>`:`<p>${esc(sizing.reason)}</p>`)+(sizing.requiredMassFlow!==null?line(`ṁ<sub>required</sub> = ${n(p.thrust*1000,0)} / ${n(initial.exhaust,1)} = ${n(sizing.requiredMassFlow,1)} kg/s; selected feed check = ${n(sizing.feedMassFlow,1)} kg/s`)+`<p>${esc(sizing.reason)}</p>`:''))],
  'pn is the shared nozzle-inlet pressure; all pressures are absolute. G is compressible-orifice mass flux. The tank-pressure inventory boundary does not imply rated-thrust endurance.',
  'Gas above the pressure boundary is not guaranteed full-thrust inventory. Feed diameter, nozzle throats, gas cooling and competing attitude jets all matter. The helper only sizes the initial state; it adds no reserve for pressure decline or simultaneous attitude jets.',
  optimistic?'Optimistic comparison: the pressure and flow limits are independent and can be mutually unattainable. Any contact pass must be read with that qualification.':'Hydraulic consistency only: regulator temperature and effective exhaust speed are held at the pre-solve pressure ceiling while nozzle pressure is solved. No temperature recalculation at pn, transient plenum, line heating or regulator dynamics is included.'));

 cards.push(card('06','thrust','How quickly do the jets spend the gas?',
  'F = ṁ v<sub>e</sub>; &nbsp; J<sub>scalar</sub> = ∫ ΣF<sub>i</sub> dt',
  `The run expels <strong>${n(r.gasUsed,1)} kg</strong>; peak total flow is <strong>${n(r.maxFlow,1)} kg/s</strong>.`,[
  step('Start with a constant-exhaust reference.',line(`ṁ = F/v<sub>e</sub> = ${n(p.thrust*1000,0)} N / ${n(p.exhaust,0)} m/s = ${n(p.thrust*1000/p.exhaust,1)} kg/s`)+`<p>This is the selected underside thrust divided by nominal exhaust speed, before cold-gas, throat and feed restrictions. It is not the simulation’s actual instantaneous flow.</p>`),
  step('Apply initial supply restrictions.',`<p>Calculated initial effective exhaust speed is ${n(initial.exhaust,1)} m/s. The four-nozzle force ceiling is ${n(4*supply.downCap/1000,1)} kN before ${optimistic?'the optimistic independent bound':'the consistent feed solve'}. The initial ${optimistic?'tank-to-ambient flow upper bound':'feed capacity evaluated at the pressure ceiling'} is ${n(sizing.feedMassFlow,1)} kg/s. Every jet draws from the same feed; actual forces may be lower.</p>`),
  step('Compare ideal inventory impulse with the integrated run.',line(`J<sub>ideal reference</sub> = m<sub>gas</sub>v<sub>e</sub> = ${n(p.gas,0)} × ${n(p.exhaust,0)} = ${n(p.gas*p.exhaust/1000,1)} kN·s`)+line(`J<sub>scalar, run</sub> = ${n(r.impulse/1000,1)} kN·s; &nbsp; gas remaining = ${n(r.final.gas,1)} kg`))],
  'F is force (N), ṁ mass flow (kg/s), ve effective exhaust speed (m/s), and J impulse (N·s). ΣFi is the sum of individual jet magnitudes.',
  `${p.allThrustersOff?'Every thruster is disabled in this comparison. ':''}The ideal inventory reference assumes all gas is available at constant exhaust speed. Actual pressure, cooling, valves, throats and attitude commands constrain it. Opposed jets spend gas but can cancel force; scalar impulse is not upward or net vehicle impulse.`));

 const release=ramp?.releaseState??r.samples.find(s=>s.phase!=='ramp'),wetI=[m*(1.95**2+1.2**2)/12,m*(4.6**2+1.2**2)/12,m*(4.6**2+1.95**2)/12].map(v=>v*p.inertiaScale);
 cards.push(card('07','motion','How do the jets translate and rotate the car?',
  'm <b>a</b> = m <b>g</b> + <b>F</b><sub>drag</sub> + R(q) Σ<b>F</b><sub>i</sub>; &nbsp; I<b>ω̇</b> + <b>ω</b> × (I<b>ω</b>) = <b>τ</b>',
  ramp&&!ramp.released?'The ramp stopped, so <strong>no airborne state was integrated</strong>.':`The flight starts with the ${ramp?'calculated ramp':'selected'} velocity and rotation, then integrates <strong>all three rotation axes</strong>.`,[
  step('Calculate changing mass and rotational inertia.',line(`m(t) = ${n(m,0)} − ${n(p.gas,0)} + m<sub>gas</sub>(t) kg`)+line('I<sub>x</sub> = km(w²+h²)/12; I<sub>y</sub> = km(l²+h²)/12; I<sub>z</sub> = km(l²+w²)/12')+`<p>At full inventory, diagonal I = (${wetI.map(x=>n(x,0)).join(', ')}) kg·m². The assumed body is 4.6 × 1.95 × 1.2 m; inertia multiplier k=${n(p.inertiaScale,2)}.</p>`),
  step('Sum force and moment for each nozzle.',line('τ<sub>jets</sub> = Σ [(r<sub>nozzle</sub> − r<sub>CG</sub>) × F<sub>i</sub>]')+`<p>Body-frame jet forces are rotated into world coordinates using quaternion q. The angular equation also includes aerodynamic moment and gyroscopic coupling. One jet can change translation and rotation together.</p>`),
  step('Carry the actual release state into flight.',release?line(`v<sub>release</sub> = (${n(release.vx,2)}, ${n(release.vLateral,2)}, ${n(release.vy,2)}) m/s; &nbsp; ω = (${release.w.map(v=>n(v,3)).join(', ')}) rad/s`):'<p>No release occurred in this run.</p>'),
  step('State the controller choices.',`<p>Flip direction: <strong>${p.flipMode==='continue'?'continue inherited rotation when substantially inverted':'shortest path to upright'}</strong>. Heading target: <strong>${p.headingMode==='outbound'?'outbound horizontal release velocity (rear toward ramp in the demo case)':p.headingMode==='release'?'release/ramp heading':'world heading zero'}</strong>. Lateral-velocity target: <strong>${n(p.lateralVelocityTarget??0,2)} m/s</strong>, measured transverse to the selected heading target. Roll correction, heading correction and lift compete for the same gas; a sideways-speed failure can therefore be caused by this selected controller.</p>`),
  step('Delay and limit commands.' ,`<p>Commands wait ${n(p.controlDelay,0)} ms before a valve response with ${n(p.valveLag,0)} ms time constant. Nozzle allocation obeys positive-only force, per-jet limits and the shared gas feed.</p>`)],
  'Bold/vector quantities are expressed here using components: world velocity order is forward x, lateral y, vertical z. ω is body-axis angular velocity; I is the assumed diagonal inertia tensor; R(q) rotates body vectors into the world.',
  'The simulator uses a generic controller and assumed nozzle positions. CG offsets are fixed; tank-by-tank gas redistribution and a measured full inertia tensor are not available. The equations describe this model, not Tesla’s undisclosed controller. A selected stuck-closed jet is removed from the allocator; no fault-specific landing strategy or detection process is modeled.'));

 cards.push(card('08','contact','What actually touches the ground, and how fast?',
  'v<sub>contact</sub> = v<sub>CG</sub> + R(q) [ω × r<sub>contact−CG</sub>]',
  ramp&&!ramp.released?'No airborne landing occurred; <strong>contact results are not applicable</strong>.':!r.landed?'The run ended before ground contact; <strong>these are final-state diagnostics, not touchdown measurements</strong>.':`First-contact descent is <strong>${n(r.contactVerticalSpeed,2)} m/s</strong>; sideways speed is <strong>${n(r.lateralSpeed,2)} m/s</strong>; longitudinal speed is <strong>${n(r.longitudinalSpeed,2)} m/s</strong> (${r.longitudinalSpeed<0?'backward':'forward'} relative to the nose).`,[
  step('Include rotation at the first touching point.',`<p>The lowest rigid-body corner is found from the quaternion at each step. A rotation term is added to CG velocity, rather than treating the whole vehicle as one falling point. ${r.landed?`CG descent at contact is ${n(r.verticalSpeed,2)} m/s, while first-point descent is ${n(r.contactVerticalSpeed,2)} m/s.`:'No touchdown comparison is reported for this run.'}</p>`),
  step('Apply the selected speed and attitude limits.',`<p>Downward contact speed ≤ ${n(p.contactSpeedLimit,2)} m/s; sideways speed ≤ ${n(p.sideSpeedLimit,2)} m/s; |longitudinal speed| ≤ ${n(p.longitudinalSpeedLimit??1.5,2)} m/s, applying equally forward and backward; upright tilt ≤ 8°; total angular speed ≤ 12°/s.</p>${r.landed?line(`Measured in this run: ${n(r.contactVerticalSpeed,2)} m/s; ${n(r.lateralSpeed,2)} m/s sideways; ${n(r.longitudinalSpeed,2)} m/s longitudinal; ${n(r.pitchError,2)}°; ${n(r.angularSpeed,2)}°/s`):''}`),
  step('Combine landing and hardware checks.',`<p>${r.candidate?(optimistic?'The selected landing and hardware checks pass under the optimistic feed bound.':'The selected landing and hardware checks all pass.'):r.soft?(optimistic?'Landing-speed and attitude checks pass under the optimistic feed bound, but a hardware screen fails.':'Landing-speed and attitude checks pass, but at least one hardware screen fails.'):'The selected overall checks do not pass.'} ${esc(r.reason)}</p>`)],
  'rcontact−CG is the body-frame vector from CG to contact point. Downward speed is the negative vertical component, clipped at zero. Sideways speed is relative to the body heading. Signed longitudinal speed is positive forward along the nose and negative backward; its absolute value is screened.',
  'The default 1.5 m/s longitudinal limit is a chosen small-residual-motion proxy (5.4 km/h), not a tyre landing-speed limit. It uses the same numerical scale as the vertical screen, with no physical equivalence implied. Forward and backward are treated alike because tyre spin-up, rolling, braking and runway are not modeled. A wheeled vehicle can tolerate much higher longitudinal speed. All thresholds are adjustable screening assumptions, not vehicle safety standards. Ground contact ends the simulation: tyre impact, suspension travel, restraint loads and post-landing stopping distance are not calculated.'));

 cards.push(card('09','cooling','Where does the cold come from?',
  p.blowdown?'s<sub>remaining gas</sub> = constant; &nbsp; h<sub>regulator,in</sub> = h<sub>regulator,out</sub>':'Q̇ = ṁ (T/ρ) (∂p/∂T)<sub>ρ</sub>',
  r.eosInvalidState?'Temperature minimum unavailable: the run leaves the validated EOS domain.':`Coldest tank gas: <strong>${n(r.minimumTemperature-273.15,1)} °C</strong>. ${r.hasGasFlow?`Coldest flowing regulator gas: <strong>${n(r.minimumFeedTemperature-273.15,1)} °C</strong>.`:'<strong>Regulator inactive:</strong> no gas was discharged.'}`,[
  step('Account for gas leaving a rigid tank.',line('d(mu)/dt = Q̇ − ṁ h<sub>out</sub>')+`<p>In the adiabatic, well-mixed approximation (Q̇=0), remaining gas follows constant entropy. For ideal gas, T/T₀=(m/m₀)<sup>γ−1</sup>. ${reference?'The reference '+fluidWord+' table is evaluated at constant initial entropy and the current density.':p.realGas?'The optional PR model solves its own entropy relation.':'Ideal air uses γ=1.4.'}</p>`),
  step('Treat regulation as a different process.',`<p>The regulator is an approximately constant-enthalpy pressure drop. ${p.realGas?'Real-'+fluidWord+' outlet temperature is solved from the EOS; it can differ from tank temperature.':'Ideal air has no Joule–Thomson temperature change.'} The feed targets ${n(regulator.regulatorBar,0)} bar before an assumed ${n(regulator.deliveryLossPercent,1)}% pressure loss, limited by remaining tank pressure. The hydraulic feed solve can lower nozzle pressure below that ceiling, but this version retains the ceiling-state regulator temperature and exhaust speed. Nozzle expansion can cool the gas further.</p>`),
  step('Make the isothermal heat requirement explicit.',line('Q̇<sub>isothermal</sub> = ṁ (T/ρ) (∂p/∂T)<sub>ρ</sub>; ideal gas: Q̇ = ṁRT')+`<p>${p.blowdown?'Adiabatic mode is selected, so the run supplies no external heat.':'Isothermal comparison is selected: peak heat transfer is '+n(r.maxHeatPower/1e6,2)+' MW and total supplied heat is '+n(r.heatRequired/3.6e6,3)+' kWh, compared with an assumed '+n(p.heatTransferPower/1000,2)+' MW heat-transfer capacity.'}</p>`),
  step('Compare with the chosen cold-component screen.',line(`T<sub>minimum allowed</sub> = ${n(p.minimumGasTemperature,0)} °C`)+`<p>${r.eosInvalidState?'The property model left its validated domain, so a thermal pass cannot be established.':r.thermalFits?'The calculated gas temperatures remain within that assumed limit.':'The calculated gas temperatures fall below that assumed limit.'}</p>`)],
  'u is specific internal energy, h specific enthalpy, s specific entropy, ρ gas density, and Q̇ heat entering the gas. Temperature-dependent properties come from the selected gas model.',
  'Gas temperature is not the same as transient wall or seal temperature. The operating limit is assumed. Tank-wall heat transfer, moisture icing, two-phase nozzle flow and heat-exchanger size/mass remain unresolved; this screen does not prove material failure.',eosTemperatureCaveat));
 return cards.join('\n');
}
